// Generates sbom.cdx.json (CycloneDX 1.5): dependency metadata from the
// lockfile plus a file inventory of the release tarball. Deterministic —
// the serialNumber is a UUIDv5 derived from the recorded hashes and no
// timestamp is emitted, so identical inputs yield an identical SBOM.
const fs = require("fs");
const crypto = require("crypto");

const pkg = require("./package.json");
const lock = require("./package-lock.json");

const SHIPPED = [
  "package.json",
  "index.js",
  "build.js",
  "sbom.js",
  "release.sh",
  "README.md",
  "package-lock.json",
  "dist/my-package.js",
];

const sha256 = (f) => crypto.createHash("sha256").update(fs.readFileSync(f)).digest("hex");
const purl = (name, version) => `pkg:npm/${name}@${version}`;
const rootRef = purl(pkg.name, pkg.version);

const depEntries = Object.entries(lock.packages).filter(([k]) => k.startsWith("node_modules/"));

const components = depEntries.map(([path, entry]) => {
  const name = path.replace(/^node_modules\//, "");
  const [, alg, b64] = entry.integrity.match(/^(sha\d+)-(.+)$/);
  return {
    type: "library",
    "bom-ref": purl(name, entry.version),
    name,
    version: entry.version,
    purl: purl(name, entry.version),
    licenses: [{ license: { id: entry.license } }],
    hashes: [{ alg: alg.replace("sha", "SHA-").toUpperCase(), content: Buffer.from(b64, "base64").toString("hex") }],
  };
});

for (const file of SHIPPED) {
  components.push({
    type: "file",
    "bom-ref": `file:${file}`,
    name: file,
    hashes: [{ alg: "SHA-256", content: sha256(file) }],
  });
}

// UUIDv5 (SHA-1 based, RFC 4122) in the DNS namespace, over the component inventory.
const DNS_NS = Buffer.from("6ba7b8109dad11d180b400c04fd430c8", "hex");
const digest = crypto
  .createHash("sha1")
  .update(DNS_NS)
  .update(JSON.stringify(components.map((c) => c["bom-ref"] + JSON.stringify(c.hashes))))
  .digest();
digest[6] = (digest[6] & 0x0f) | 0x50;
digest[8] = (digest[8] & 0x3f) | 0x80;
const hex = digest.toString("hex").slice(0, 32);
const serialNumber = `urn:uuid:${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;

const bom = {
  $schema: "http://cyclonedx.org/schema/bom-1.5.schema.json",
  bomFormat: "CycloneDX",
  specVersion: "1.5",
  serialNumber,
  version: 1,
  metadata: {
    tools: [{ vendor: pkg.name, name: "sbom.js", version: pkg.version }],
    component: {
      type: "application",
      "bom-ref": rootRef,
      name: pkg.name,
      version: pkg.version,
      purl: rootRef,
      licenses: [{ license: { id: pkg.license } }],
      hashes: [{ alg: "SHA-256", content: sha256(`${pkg.name}-${pkg.version}.tgz`) }],
    },
  },
  components,
  dependencies: [
    { ref: rootRef, dependsOn: components.filter((c) => c.type === "library").map((c) => c["bom-ref"]) },
    ...depEntries.map(([path, entry]) => ({
      ref: purl(path.replace(/^node_modules\//, ""), entry.version),
      dependsOn: [],
    })),
  ],
};

fs.writeFileSync("sbom.cdx.json", JSON.stringify(bom, null, 2) + "\n");
console.log(`SBOM: sbom.cdx.json (${components.length} components)`);
